// Methods that store from a for-in or for-of head where sloppy mode and
// strict mode differ: into an undeclared name (sloppy mode creates a
// global) and into a property of a string (sloppy mode drops the store).
var shapes = {};
shapes.Bag = function (size) {
  this.size = size;
};
shapes.Bag.prototype.lastKey = function () {
  for (bagLastKey in { first: 1, last: 2 });
  return bagLastKey + " " + this.size;
};
shapes.Cell = function (label) {
  this.label = label;
};
shapes.Cell.prototype.lastItem = function () {
  var label = this.label;
  for (label.item of [1, 2, 3]);
  return typeof label.item;
};
module.exports = { shapes: shapes };
